# Remove peaks that fall in ENCODE blacklist regions - artefact-prone loci
# (centromeres, telomeres, satellite repeats) that attract spurious signal in
# every ChIP/CUT&Tag experiment regardless of the antibody. Filtering happens
# before consensus and counting so artefacts do not propagate downstream.
#
# The ENCODE v2 blacklists for hg38 (636 regions) and mm10 (3435 regions) are
# inlined below as base64-gzip so BOTH the script tools and the rendered notebook
# can filter offline: the notebook runs in the user's project directory, which has
# no plugin asset tree, so a shipped BED file would be unreachable there. Pass
# --blacklist BED to override, or --genome hg38|mm10 to select the inlined list.
# Other builds need a user blacklist path; with neither, this step skips.
# Source: Amemiya HM, Kundaje A, Boyle AP. The ENCODE Blacklist: identification of
# problematic regions of the genome. Sci Rep 9, 9354 (2019).
# doi:10.1038/s41598-019-45839-z  (Boyle-Lab/Blacklist, ENCODE v2 lists).

.blacklist_b64 <- list(
  hg38 = "",
  mm10 = ""
)

# Decode an inlined blacklist to a temp BED. jsonlite::base64_dec + memDecompress
# are available in the plugin environment (jsonlite is a core dependency).
decode_blacklist <- function(build) {
  b64 <- .blacklist_b64[[tolower(build)]]
  if (is.null(b64)) return(NULL)
  bed <- memDecompress(jsonlite::base64_dec(b64), type = "gzip", asChar = TRUE)
  path <- tempfile(pattern = paste0(tolower(build), "-blacklist-"), fileext = ".bed")
  cat(bed, file = path)
  path
}

blacklist_file <- NULL
if (!is.null(blacklist_path) && nzchar(blacklist_path)) {
  if (!file.exists(blacklist_path)) stop("blacklist not found: ", blacklist_path, call. = FALSE)
  blacklist_file <- blacklist_path
} else if (!is.null(genome) && nzchar(genome) && tolower(genome) %in% names(.blacklist_b64)) {
  blacklist_file <- decode_blacklist(genome)
  cat(sprintf("using inlined ENCODE v2 blacklist for %s\n", tolower(genome)))
}

if (is.null(blacklist_file)) {
  cat("no blacklist provided (pass --blacklist BED or --genome hg38/mm10); skipping blacklist filter\n")
} else {
  blacklist <- rtracklayer::import(blacklist_file)
  cat(sprintf("blacklist: %d regions from %s\n", length(blacklist), basename(blacklist_file)))

  removed <- list()
  if (!is.null(peak_list)) {
    before <- vapply(peak_list, length, integer(1))
    peak_list <- GRangesList(lapply(peak_list, function(peaks) {
      peaks[!IRanges::overlapsAny(peaks, blacklist)]
    }))
    after <- vapply(peak_list, length, integer(1))
    for (name in names(peak_list)) {
      removed[[name]] <- as.integer(before[[name]] - after[[name]])
      cat(sprintf("%s: removed %d blacklisted peaks (%d -> %d)\n",
                  name, removed[[name]], before[[name]], after[[name]]))
    }
  }
  if (!is.null(consensus_peaks)) {
    before <- length(consensus_peaks)
    consensus_peaks <- consensus_peaks[!IRanges::overlapsAny(consensus_peaks, blacklist)]
    removed$consensus <- as.integer(before - length(consensus_peaks))
  }
  blacklist_removed <- removed
}
analysis_steps <- c(analysis_steps, "blacklist-filter")
